<?php $source=(string)($_GET['source'] ?? ''); $groups=tr_section_groups(); if (!isset($groups[$source])) { tr_hero('Missing section', 'Section not found', 'The requested project section does not exist in the loaded data.'); echo '<p><a class="button" href="?page=sections">Back to sections</a></p>'; return; } $g=$groups[$source]; $rows=tr_page_records($g['records']); tr_hero('Project section', $g['title'], 'All normalized owner records loaded from '.$source.'. Open any item for full detail or open the source JSON for the raw document.'); ?>
<form class="filters compact" method="get"><input type="hidden" name="page" value="section"><input type="hidden" name="source" value="<?= tr_e($source); ?>"><label>Filter this section <input name="q" value="<?= tr_e($_GET['q'] ?? ''); ?>" placeholder="type a record, cue, fixture, status..."></label><button>Filter</button><a class="button ghost" href="<?= tr_e(tr_url(['page'=>'section','source'=>$source])); ?>">Reset</a></form>
<section class="panel"><h2>Section actions</h2><p><a class="button" href="<?= tr_e(tr_source_url($source)); ?>">Open source JSON</a> <a class="button ghost" href="?page=sections">All sections</a></p></section>
<section class="panel"><h2>Records in this section</h2><?php tr_owner_table($rows); ?></section><div class="cards"><?php foreach ($rows as $r) tr_record_card($r); ?></div>
